class Solution {
  public long countSubarrays(int[] nums, long k) {
    int n = nums.length;
    int[] maxDq = new int[n], minDq = new int[n];
    int mh = 0, mt = 0, nh = 0, nt = 0, left = 0;
    long total = 0;
    for (int r = 0; r < n; r++) {
      while (mt > mh && nums[maxDq[mt - 1]] <= nums[r]) mt--;
      maxDq[mt++] = r;
      while (nt > nh && nums[minDq[nt - 1]] >= nums[r]) nt--;
      minDq[nt++] = r;
      while ((long) (nums[maxDq[mh]] - nums[minDq[nh]]) * (r - left + 1) > k) {
        left++;
        if (maxDq[mh] < left) mh++;
        if (minDq[nh] < left) nh++;
      }
      total += r - left + 1;
    }
    return total;
  }
}
